// Adzuna returns at most 50 jobs per page; 5 pages covers a normal day per term
const terms = ['product manager', 'produktmanager', 'product owner'];
const pages = [1, 2, 3, 4, 5];
return terms.flatMap(term => pages.map(page => ({ json: { term, page } })));

// Same job, different spelling: "IMAGO" vs "Imago", "(m/w/d)" vs "(m/w/x)"
const normalise = text => (text || '')
  .toLowerCase()
  .replace(/\((?:[mwfdxg]\s*\/\s*)+[mwfdxg]\)|\(gn\)|\(all genders\)/g, '')
  .replace(/[^a-z0-9äöüß]+/g, ' ')
  .trim();

return $input.all().map(({ json: j }) => ({
  json: {
    id: j.id,
    key: `${normalise(j.title)} | ${normalise(j.company?.display_name)}`,
    title: j.title,
    company: j.company?.display_name ?? '',
    location: j.location?.display_name ?? '',
    contract: j.contract_time,
    published: j.created,
    url: j.redirect_url,
    description: j.description,
  },
}));

// Runs once a day, so a 24 h window shows each job exactly once without storing state
const since = Date.now() - 24 * 60 * 60 * 1000;
return $input.all().filter(i => Date.parse(i.json.published) > since);

const profile = $input.first().json.data;
const jobs = $('Only jobs from the last 24 h').all().map(i => i.json);
const size = 20;

const instructions = `You screen job ads for one candidate. Score each job 0-100 for how well it fits the candidate profile.

Scoring guide:
- 80-100: Senior/Lead PM role in a strong-fit domain, English-friendly, reachable location
- 60-79: real PM role with one clear gap (domain, seniority or location)
- 40-59: PM role with several gaps, or German requirement unclear
- 0-39: not a product management role, junior/student/intern, requires fluent German, or a weak-fit domain
Hard rules:
- Not a product management role (e.g. customer education, marketing, sales, engineering, project management): score at most 30.
- Job ad written in German, or requiring fluent/business German: score at most 50, because the candidate speaks German at A2 level.

Return only a JSON array, no other text: [{"id": "<job id>", "score": <0-100>, "reason": "<max 15 words>"}]`;

const out = [];
for (let i = 0; i < jobs.length; i += size) {
  const batch = jobs.slice(i, i + size);
  const list = batch
    .map(j => `### id: ${j.id}\nTitle: ${j.title}\nCompany: ${j.company}\nLocation: ${j.location}\n${j.description}`)
    .join('\n\n');
  out.push({ json: { jobs: batch, prompt: `${instructions}\n\n# Candidate profile\n${profile}\n\n# Jobs\n${list}` } });
}
return out;

// Gemini answers one batch per item, in the same order as the batches
const batches = $('Batches of 20').all();

// Gemini ignores the prompt's German-ad cap, so enforce it here.
// Raise GERMAN_MAX once the candidate's German is good enough.
const GERMAN_MAX = 50;
const DE = /\b(und|wir|sie|du|dich|dein|deine|ihre|unser|unsere|für|mit|bei|auf|der|die|das|ist|eine|einen|sowie|erfahrung|kenntnisse|aufgaben|abgeschlossenes|studium)\b/g;
const EN = /\b(and|we|you|your|our|the|with|for|of|to|is|are|experience|skills|team)\b/g;
const isGerman = text => {
  const t = (text || '').toLowerCase();
  return (t.match(DE) || []).length > (t.match(EN) || []).length;
};
return $input.all().flatMap((item, i) => {
  const text = (item.json.steps || [])
    .filter(s => s.type === 'model_output')
    .flatMap(s => s.content || [])
    .filter(c => c.type === 'text')
    .map(c => c.text)
    .join('');
  let scores = [];
  try {
    scores = JSON.parse(text.replace(/```(json)?/g, '').trim());
  } catch (e) {}
  const byId = Object.fromEntries(scores.map(s => [String(s.id), s]));
  return batches[i].json.jobs.map(job => {
    const german = isGerman(`${job.title} ${job.description}`);
    let score = byId[job.id]?.score ?? null;
    if (german && typeof score === 'number') score = Math.min(score, GERMAN_MAX);
    return { json: { ...job, german, score, reason: byId[job.id]?.reason ?? 'not scored' } };
  });
});

// Show only good fits; padding with weak jobs hides the good ones
const MIN_SCORE = 60;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const jobs = $input.all().map(i => i.json);
const german = jobs.filter(j => j.german).length;
const good = jobs
  .filter(j => typeof j.score === 'number' && j.score >= MIN_SCORE)
  .sort((a, b) => b.score - a.score)
  .slice(0, 10);
const date = new Date().toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short', timeZone: 'Europe/Berlin' });

const lines = good.map((j, n) =>
  `${n + 1}. <b>${j.score}</b> · <a href="${esc(j.url)}">${esc(j.title)}</a>\n` +
  `${esc(j.company)} · ${esc(j.location)}${j.german ? ' · 🇩🇪 German ad' : ''}\n<i>${esc(j.reason)}</i>`);

const header = `<b>JobPilot · ${date}</b>\n${jobs.length} new PM jobs · <b>${good.length} good fits</b> (${MIN_SCORE}+) · ${german} in German`;
const body = good.length ? lines.join('\n\n') : 'No good fits today.';
return [{ json: { text: `${header}\n\n${body}` } }];
